{
  "requirement_definitions": [
    {
      "id": "DMSR-5606",
      "title": "Data Access Center Simultaneous Connections",
      "text": "At least dacMinConnections simultaneous connections shall be supported at each Data Access Center."
    },
    {
      "id": "DMSR-8204",
      "title": "Access to catalogs for external Level 3 processing",
      "text": "The DMS shall facilitate Level 3 catalog processing that may take place at external facilities outside the DACs. This will principally be by facilitating the export of catalogs and the provision of tools for maintaining and validating exported data."
    },
    {
      "id": "DMSR-7887",
      "title": "Access to images for external Level 3 processing",
      "text": "The DMS shall facilitate Level 3 image processing that may take place at external facilities outside the DACs. This will principally be by facilitating the export of image datasets and the provision of tools for maintaining and validating exported data."
    },
    {
      "id": "DMSR-3171",
      "title": "Access to input catalogs for DAC-based Level 3 processing",
      "text": "The DMS shall provide access to all Level 1 and Level 2 catalog products through the LSST project’s Data Access Centers, and any others that have been established and funded, for Level 3 processing that takes place at the DACs."
    },
    {
      "id": "DMSR-3481",
      "title": "Access to input images for DAC-based Level 3 processing",
      "text": "The DMS shall provide access to all Level 1 and Level 2 image products through the LSST project’s Data Access Centers, and any others that have been established and funded, for Level 3 processing that takes place at the DACs."
    },
    {
      "id": "DMSR-9225",
      "title": "Federation with external catalogs",
      "text": "The DMS shall provide a means for federating Level 1, 2, and 3 catalogs with externally provided catalogs, for joint analysis. The DMS shall provide speciﬁcations for how external data must be provided in order for this to be achieved. The DMS shall strive to support community standards in this regard, including, but not limited to, virtual observatory facilities that may be available during the project lifetime."
    },
    {
      "id": "DMSR-8503",
      "title": "Data Access Center Geographical Distribution",
      "text": "The Data Access Centers will be hosted at facilities selected in at least the U.S. and the observatory host country to permit widest possible access to LSST data with the fewest possible network hops."
    },
    {
      "id": "DMSR-4495",
      "title": "No Limit on Data Access Centers",
      "text": "The number of Data Access Centers shall be limited only by available internal or external funding. No architectural constraints will be placed on the DMS that prohibit the addition of Data Access Centers at any time, subject to funding."
    },
    {
      "id": "DMSR-6710",
      "title": "Calculation of Photometric Performance Metrics",
      "text": "The DMS shall include software to enable the calculation of the photometric performance metrics deﬁned in OSS-REQ-0387."
    }
  ],
  "allocation_entries": []
}
